function relativeTime(iso) {
    const then = new Date(iso).getTime();
    if (Number.isNaN(then)) return '';
    const sec = Math.round((Date.now() - then) / 1000);
    if (sec < 45) return 'now';
    if (sec < 3600) return `${Math.round(sec / 60)}m ago`;
    if (sec < 86400) return `${Math.round(sec / 3600)}h ago`;
    return `${Math.round(sec / 86400)}d ago`;
}
/** "14:32" label for session dividers. */ function sessionTime(iso) {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '';
    return d.toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit'
    });
}
/** Coarse day bucket for the date separators in the list. */ function dateGroup(iso) {
    const then = new Date(iso);
    if (Number.isNaN(then.getTime())) return 'Earlier';
    const startOfToday = new Date();
    startOfToday.setHours(0, 0, 0, 0);
    const dayMs = 86400000;
    if (then.getTime() >= startOfToday.getTime()) return 'Today';
    if (then.getTime() >= startOfToday.getTime() - dayMs) return 'Yesterday';
    if (then.getTime() >= startOfToday.getTime() - 7 * dayMs) return 'This week';
    return 'Earlier';
}
